// Journal en anglais, semaine du 19 octobre 2026 : événements du 12 au 18 octobre 2026, rédigés à partir des fiches ACT de la même semaine.
// Textes originaux ; seuls les faits et déclarations des fiches sont repris.
import type { LanguageExerciseDef } from "../helpers";
import type { NewsReport } from "./news-listening";

type Opt = [text: string, justification: string];
const id = (n: number) => `EN-NEWS-2026W43-${String(n).padStart(3, "0")}`;

function news(n: number, title: string, text: string, question: string, correct: "a" | "b" | "c", opts: [Opt, Opt, Opt]): LanguageExerciseDef {
  return {
    exerciseId: id(n),
    subjectCode: "EN",
    kind: "listening",
    title,
    level: "B2",
    text,
    transcriptByDefault: false,
    question,
    options: opts.map(([t, j], i) => {
      const oid = ["a", "b", "c"][i];
      return { id: oid, text: t, correct: oid === correct, justification: j };
    }),
  };
}

function rep(n: number, slug: string, category: string, headline: string, report: string, vocabulary: [string, string][]): NewsReport {
  return { exerciseId: id(n), slug, category, headline, report, vocabulary: vocabulary.map(([term, fr]) => ({ term, fr })) };
}

